<?php ob_start(); ?><div class="page-head"><div><h1>Users</h1><p>Manage accounts and access roles.</p></div><a class="primary button" href="/users/create">+ New user</a></div><form class="toolbar"><input name="search" value="<?=e($search)?>" placeholder="Search name or email"><button>Search</button></form><div class="panel table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Roles</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['roles']??'—')?></td><td><span class="badge"><?=e($u['status'])?></span></td><td><?=e($u['created_at'])?></td><td><a href="/users/<?=$u['id']?>/edit">Edit</a> <form class="inline" method="post" action="/users/<?=$u['id']?>/delete" onsubmit="return confirm('Delete this user?')"><?=\App\Core\Csrf::field()?><button class="danger-link">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$users): ?><tr><td colspan="6">No users found.</td></tr><?php endif; ?></tbody></table></div><?php $pages=max(1,(int)ceil($total/20));if($pages>1): ?><div class="pagination"><?php for($p=1;$p<=$pages;$p++): ?><a class="<?= $p===$page?'active':'' ?>" href="?search=<?=urlencode($search)?>&page=<?=$p?>"><?=$p?></a><?php endfor; ?></div><?php endif; ?><?php $content=ob_get_clean();$title='Users';require dirname(__DIR__).'/layouts/app.php';
